const webhookEmail = ($input.first()?.json?.query?.email || '').toLowerCase();
const detectItems = $('Detect Duplicate1').all();

const match = detectItems.find(it => (it.json.email_address || '').toLowerCase() === webhookEmail);

if (!match) {
  return [{ json: { email_address: webhookEmail, first_name: '(unknown)', last_name: '', existing_emp_id: null } }];
}

return [{ json: match.json }];

const s = (v) => (v === null || v === undefined) ? '' : String(v).trim();

const out = [];
const requiredFields = [
  'Email Address',
  'First Name',
  'Last Name',
  'Start Date',
  'Phone Number',
  'Detailed House Address',
  'Account Number',
  'Account Name',
  'Bank Name',
  'Designation (as it is contained on your offer letter with Anchor)'
];

for (const item of $input.all()) {
  const row = item.json;
  const errors = [];

  for (const f of requiredFields) {
    if (s(row[f]) === '') errors.push(`Missing: ${f}`);
  }

  const email = s(row['Email Address']).toLowerCase();
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    errors.push('Invalid email format.');
  }

  const rawDate = s(row['Start Date']);
  let normalizedStartDate = rawDate;
  if (rawDate) {
    let sd;
    const mdy = rawDate.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (mdy) {
      const [, m, d, y] = mdy;
      sd = new Date(Number(y), Number(m) - 1, Number(d));
      normalizedStartDate = `${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
    } else {
      sd = new Date(rawDate);
    }

    if (isNaN(sd.getTime())) {
      errors.push('Start Date is not a valid date.');
    } else {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      sd.setHours(0, 0, 0, 0);
      if (sd < today) errors.push('Start Date cannot be in the past.');
    }
  }

  out.push({
    json: {
      email_address: email,
      first_name: s(row['First Name']),
      middle_name: s(row['Middle Name']),
      last_name: s(row['Last Name']),
      designation: s(row['Designation (as it is contained on your offer letter with Anchor)']),
      phone_number: s(row['Phone Number']),
      house_address: s(row['Detailed House Address']),
      start_date: normalizedStartDate,
      account_number: s(row['Account Number']),
      account_name: s(row['Account Name']),
      bank_name: s(row['Bank Name']),
      tax_id: s(row['Tax ID (Optional)']),
      tshirt_size: s(row['T-Shirt Size']),
      headshot_url: s(row['Headshot']),
      hasErrors: errors.length > 0,
      errors
    }
  });
}

return out;

const formItems = $('Validate Form Data1').all();
const lookupItems = $input.all();

const out = formItems.map((formItem, idx) => {
  const lookupRow = lookupItems[idx]?.json || {};
  const isDuplicate = Object.keys(lookupRow).length > 0 && !!lookupRow.email_address;
  return {
    json: {
      ...formItem.json,
      isDuplicate,
      existing_emp_id: lookupRow.emp_id || null
    }
  };
});

return out;

const webhookEmail = ($input.first()?.json?.query?.email || '').toLowerCase();
const detectItems = $('Detect Duplicate1').all();

const match = detectItems.find(it => (it.json.email_address || '').toLowerCase() === webhookEmail);

if (!match) {
  throw new Error(`Could not restore form data for approved duplicate: ${webhookEmail}`);
}

return [{ json: match.json }];

function shortId() {
  const hex = '0123456789abcdef';
  let s = '';
  for (let i = 0; i < 8; i++) {
    s += hex[Math.floor(Math.random() * 16)];
  }
  return s.toUpperCase();
}

const out = [];

for (const item of $input.all()) {
  const nowIso = new Date().toISOString();
  out.push({
    json: {
      ...item.json,
      emp_id: `EMP-${shortId()}`,
      status: 'Onboarding',
      created_at: nowIso,
      last_modified: nowIso
    }
  });
}

return out;

const out = [];

for (const item of $input.all()) {
  const d = item.json;
  let isUrgent = false;
  let daysUntilStart = null;

  if (d.start_date) {
    const start = new Date(d.start_date);
    if (!isNaN(start.getTime())) {
      const startUtc = Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), start.getUTCDate());
      const now = new Date();
      const todayUtc = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
      daysUntilStart = Math.ceil((startUtc - todayUtc) / 86400000);
      isUrgent = daysUntilStart <= 2;
    }
  }

  out.push({
    json: {
      ...d,
      isUrgent,
      daysUntilStart,
      urgencyPrefix: isUrgent ? '🚨 URGENT — ' : '🚀 '
    }
  });
}

return out;

const q = $input.first()?.json?.query || {};
const empId = String(q.empId || '').trim();
const name = String(q.name || '').trim();

if (!empId) {
  return [{ json: { ok: false, error: 'Missing empId', empId: '', name: '' } }];
}

if (!/^EMP-[A-F0-9]{8}$/i.test(empId)) {
  return [{ json: { ok: false, error: 'Invalid empId format', empId, name } }];
}

return [{ json: { ok: true, empId, name, confirmed_at: new Date().toISOString() } }];

// Build company_email (firstname@anchor.co) and welcome_due_at (day after start_date at 9am).
const confirmCtx = $('Validate Webhook Input1').first().json;
const empRow = $input.first()?.json || {};
const found = !!empRow.emp_id;

function toEmailLocal(name) {
  return String(name || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');
}

const firstName = empRow.first_name || '';
const companyEmail = firstName ? `${toEmailLocal(firstName)}@anchor.co` : '';

// Welcome timing: day AFTER start_date at 9:00 AM. Falls back to now+24h if unparseable.
const now = new Date();
let welcomeDueAt;
const rawStart = empRow.start_date || '';

if (rawStart) {
  let start;
  const mdy = String(rawStart).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (mdy) {
    const [, m, d, y] = mdy;
    start = new Date(Number(y), Number(m) - 1, Number(d));
  } else {
    start = new Date(rawStart);
  }
  if (!isNaN(start.getTime())) {
    start.setDate(start.getDate() + 1);
    start.setHours(9, 0, 0, 0);
    welcomeDueAt = start.toISOString();
  }
}

if (!welcomeDueAt) {
  welcomeDueAt = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
}

// Minimum 1-hour buffer (in case of backdated start_date)
const minDueAt = new Date(now.getTime() + 60 * 60 * 1000);
if (new Date(welcomeDueAt) < minDueAt) {
  welcomeDueAt = minDueAt.toISOString();
}

return [{
  json: {
    ...confirmCtx,
    found,
    employee: empRow,
    first_name: empRow.first_name || '',
    last_name: empRow.last_name || '',
    email_address: empRow.email_address || '',
    current_status: empRow.status || '',
    start_date: empRow.start_date || '',
    company_email: companyEmail,
    welcome_due_at: welcomeDueAt
  }
}];

// Filter to rows whose welcome_due_at has passed AND haven't been welcomed yet.
// Max-attempts guard: stop retrying after 14 attempts (~7 days at 30min interval).
const now = new Date();
const due = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r.welcome_due_at) continue;
  if (r.welcomed_at) continue;
  if (!r.company_email) continue;

  const dueAt = new Date(r.welcome_due_at);
  if (isNaN(dueAt.getTime())) continue;
  if (dueAt > now) continue;

  const attempts = Number(r.welcome_attempts || 0);
  if (attempts >= 14) continue;

  due.push({ json: { ...r, welcome_attempts: attempts + 1 } });
}

if (due.length === 0) return [];
return due;

// Slack returned the full users list (every user, bot, app, deleted account).
// Match by name only: new hire's first_name (lowercase) === Slack user.name.
// Then grab that user's id.

const hireCtx = $('Loop Per Hire1').item.json;
const targetName = (hireCtx.first_name || '').toLowerCase().trim();

if (!targetName) {
  return [{ json: { ...hireCtx, slack_user_id: null, lookup_ok: false, lookup_error: 'no_first_name' } }];
}

// Each input item is one Slack user. Find the one whose name matches.
let matched = null;
for (const item of $input.all()) {
  const u = item.json || {};
  if (u.deleted) continue;            // skip deactivated accounts
  if ((u.name || '').toLowerCase() === targetName) {
    matched = u;
    break;
  }
}

const slackUserId = matched?.id || null;

return [{
  json: {
    ...hireCtx,
    slack_user_id: slackUserId,
    lookup_ok: !!slackUserId,
    lookup_error: slackUserId ? null : `no_slack_user_with_name_${targetName}`
  }
}];

// Your Google Docs node returns plain text in a 'content' field (not the structured
// body.content[] tree). So we extract URLs from the flat string with regex, and pair
// each URL with the nearest non-empty line above it as its title.

const doc = $input.first().json;
// Try multiple possible field names where the text might live
let text = doc.content || doc.text || doc.body || '';
if (typeof text !== 'string') {
  // If somehow it's an object, stringify it as a last resort
  text = JSON.stringify(text);
}

// Normalize vertical tab characters (\u000b) that Google Docs sometimes uses for line breaks
text = text.replace(/\u000b/g, '\n');

const lines = text.split('\n');
const urlRegex = /https?:\/\/[^\s<>"')\]}]+/g;

// Build offset map so we can find which line each URL match lives on
const lineStarts = [];
let offset = 0;
for (const line of lines) {
  lineStarts.push(offset);
  offset += line.length + 1;
}

function lineAtOffset(off) {
  for (let i = lineStarts.length - 1; i >= 0; i--) {
    if (lineStarts[i] <= off) return i;
  }
  return 0;
}

// Find all URLs with their positions
const urls = [];
const seen = new Set();
let match;
const regex = new RegExp(urlRegex.source, 'g');
while ((match = regex.exec(text)) !== null) {
  let url = match[0].replace(/[.,;:!?)\]}>'"]+$/, '');
  if (url.length < 10) continue;
  if (seen.has(url)) continue;
  seen.add(url);

  const urlLineIdx = lineAtOffset(match.index);

  // Walk upward to find the nearest non-empty, non-URL line — that's the title
  let title = null;
  for (let i = urlLineIdx - 1; i >= 0; i--) {
    const candidate = lines[i].trim();
    if (!candidate) continue;
    if (/^https?:\/\//.test(candidate)) continue;
    title = candidate;
    break;
  }
  if (!title) title = url;

  urls.push({ url, title });
}

if (urls.length === 0) return [];

return urls.map(e => ({ json: e }));

// Deterministic ID per URL — Pinecone upsert overwrites on same ID, so re-runs don't duplicate.
function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

const out = [];
for (const item of $input.all()) {
  const url = item.json.url;
  const docTitle = item.json.title || '';

  let norm = url.trim();
  try {
    const u = new URL(norm);
    ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','ref','fbclid','gclid'].forEach(p => u.searchParams.delete(p));
    u.hash = '';
    norm = u.toString().replace(/\/$/, '');
  } catch (e) { /* keep original on parse failure */ }

  out.push({
    json: {
      url: norm,
      doc_id: `url_${hash(norm)}`,
      doc_title: docTitle,
      ingested_at: new Date().toISOString()
    }
  });
}
return out;

// Clean extracted text & skip if too short (paywall, error, or empty page).
const item = $input.first().json;
const loopCtx = $('Loop Through URLs1').item.json;
const url = loopCtx.url;
const docId = loopCtx.doc_id;
const readingListTitle = loopCtx.doc_title || '';

// Prefer scraped <title>, fall back to the title from your reading list doc
const scrapedTitle = (item.title || '').trim();
const title = scrapedTitle || readingListTitle;

let content = (item.article_content || '').trim();
content = content.replace(/\s+/g, ' ').trim();

if (content.length < 200) {
  return [{ json: { skip: true, reason: `Too short (${content.length} chars)`, url } }];
}

if (content.length > 50000) {
  content = content.substring(0, 50000) + '...[truncated]';
}

return [{
  json: {
    skip: false,
    url,
    doc_id: docId,
    title,
    content,
    pageContent: `${title}\n\n${content}`,
    metadata: {
      sourceUrl: url,
      title: title || url,
      ingested_at: new Date().toISOString()
    }
  }
}];

// Filter Slack events: only process real human DMs to the bot.
// Drops: bot messages, edits/deletes, non-IM channels, retries, empty text.
// Also dedupes by event_id in case Slack sends a retry that beat the ack.

const body = $json.body || {};
const headers = $json.headers || {};

// Slack sends events wrapped in 'event_callback' for actual events
if (body.type !== 'event_callback') return [];

const event = body.event || {};

// Only process messages
if (event.type !== 'message') return [];

// Only direct messages
if (event.channel_type !== 'im') return [];

// Drop bot-originated messages (prevents infinite loop with our own replies)
if (event.bot_id) return [];
if (event.subtype === 'bot_message') return [];
if (event.app_id) return [];

// Drop edits/deletes/joins/etc
if (event.subtype) return [];

// Need a real user and real text
if (!event.user || !event.text) return [];
const text = String(event.text).trim();
if (!text) return [];

// Drop Slack retries — if Slack didn't get our ack in time, it'll resend.
// We already acked separately, so just ignore the retry.
const retryNum = headers['x-slack-retry-num'];
if (retryNum) return [];

return [{
  json: {
    text,
    user: event.user,
    channel: event.channel,
    ts: event.ts,
    thread_ts: event.thread_ts || event.ts,
    event_id: body.event_id,
    sessionId: `slack-${event.user}`
  }
}];
